CREATE OR REPLACE FUNCTION public.validate_admission_branch_track()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'UPDATE' then
    if new.program_offering_id = old.program_offering_id and new.track_id = old.track_id then
      return new;
    end if;
  end if;
  if not exists (
    select 1 from public.program_offerings offering
    join public.branch_track_offerings available on available.branch_id = offering.branch_id
    join public.program_tracks track on track.id = available.track_id
    where offering.id = new.program_offering_id and track.id = new.track_id
      and track.program_id = offering.program_id
      and available.is_active and offering.is_active and track.is_active
  ) then
    raise exception 'This course or strand is no longer available at the selected branch. Please choose another.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_student_branch_track()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status <> 'active' then return new; end if;
  if tg_op = 'UPDATE' then
    if old.status = 'active' and old.branch_id = new.branch_id
      and old.track_id = new.track_id and old.program_offering_id = new.program_offering_id then
      return new;
    end if;
  end if;
  perform 1 from public.admission_branches where id = new.branch_id for update;
  if not exists (
    select 1 from public.branch_track_offerings available
    join public.admission_branches branch on branch.id = available.branch_id
    join public.program_tracks track on track.id = available.track_id
    join public.program_offerings offering on offering.branch_id = branch.id and offering.program_id = track.program_id
    where branch.id = new.branch_id and track.id = new.track_id and offering.id = new.program_offering_id
      and branch.is_active and available.is_active and not available.is_deleted and track.is_active and offering.is_active
  ) then
    raise exception 'This course or strand is not available at the selected branch.';
  end if;
  return new;
end;
$function$
